import java.util.*;
public class LRUCache {
    int cap;
    LinkedHashMap<Integer,Integer> cache;
    LRUCache(int capacity) {
        this.cap = capacity;
        cache = new LinkedHashMap<>(capacity, 0.75f, true) {
            protected boolean removeEldestEntry(Map.Entry e) { return size() > cap; }
        };
    }
    public int get(int key) { return cache.getOrDefault(key, -1); }
    public void put(int key, int value) { cache.put(key, value); }
    public static void main(String[] args) {
        LRUCache c = new LRUCache(2);
        c.put(1,1); c.put(2,2); System.out.println(c.get(1));
        c.put(3,3); System.out.println(c.get(2)); // -1 evicted
    }
}

