using namespace std;
struct LRUCache {
    int cap;
    list<pair<int, int>>lst;
    unordered_map<int, list<pair<int, int>>::iterator>mp;
    LRUCache(int c):cap(c) {}
    int get(int k) {
        if (!mp.count(k))return-1;
        lst.splice(lst.begin(), lst, mp[k]);
        return mp[k]->second;
    }
    void put(int k, int v) {
        if (mp.count(k)) {
            lst.splice(lst.begin(), lst, mp[k]);
            mp[k]->second=v;
            return;
        }
        if ((int)lst.size()==cap) {
            mp.erase(lst.back().first);
            lst.pop_back();
        }
        lst.push_front({k, v});
        mp[k]=lst.begin();
    }
};

